10	inline bool use_one_mma_wg(Flash_fwd_params const& params) {
11	    // assume pack_gqa for seqlen calculation
12	    return params.arch >= 90 && (params.d == 128 || params.d == 64) && !params.is_local && 
13	        params.seqlen_q * (params.h / params.h_k) <= 64;
14	};
