16	inline bool should_pack_gqa(bool varlen_q, int seqlen_q, int qhead_per_khead, int blockM) {
17	    // If varlen, we don't actually know seqlen_q but only max_seqlen_q.
18	    if (varlen_q) return true;
19	    // Heuristic: PackGQA is a bit slower but can help if seqlen_q is small or not near a multiple of kBlockM
20	    auto round_up = [](int a, int b) { return (a + b - 1) / b * b; };
21	    float nopack_gqa_efficiency = float(seqlen_q) / float(round_up(seqlen_q, blockM));
22	    float pack_gqa_efficiency = float(seqlen_q * qhead_per_khead) / float(round_up(seqlen_q * qhead_per_khead, blockM));
23	    return nopack_gqa_efficiency < 0.9 * pack_gqa_efficiency;
24	};
