26	// Find the number of splits that maximizes the occupancy. For example, if we have
27	// batch * n_heads = 48 and we have 108 SMs, having 2 splits (efficiency = 0.89) is
28	// better than having 3 splits (efficiency = 0.67). However, we also don't want too many
29	// splits as that would incur more HBM reads/writes.
30	// So we find the best efficiency, then find the smallest number of splits that gets 85%
31	// of the best efficiency.
32	inline int num_splits_heuristic(int total_mblocks, int num_SMs, int num_n_blocks, int num_m_blocks, int size_one_kv_head, bool is_causal_or_local, int max_splits) {
33	    // If we have enough to almost fill the SMs, then just use 1 split
34	    // However, in the case of super long seqlen where each head of KV doesn't even fit into
35	    // L2 (we assume that L2 size is 50MB), we want to split.
36	    if (total_mblocks >= 0.8f * num_SMs) {
37	        int const size_l2 = 50 * 1024 * 1024;
38	        // Only split if there are enough queries to go over the KV at least twice
39	        // Don't split if causal
40	        if (size_one_kv_head > size_l2 && num_m_blocks >= num_SMs * 2 && !is_causal_or_local) {
41	            return std::min((size_one_kv_head + size_l2 - 1) / size_l2, max_splits);
42	        } else {
43	            return 1;
44	        }
45	    }
46	    // If num_n_blocks is too small, use 1 split. For example, we never split for hdim = 128 and seqlen_k = 512.
47	    if (num_n_blocks <= 4) { return 1; }
48	    max_splits = std::min({max_splits, num_SMs, num_n_blocks});
49	    float max_efficiency = 0.f;
50	    std::vector<float> efficiency;
51	    efficiency.reserve(max_splits);
52	    for (int num_splits = 1; num_splits <= max_splits; num_splits++) {
53	        float n_waves = float(total_mblocks * num_splits) / num_SMs;
54	        float eff = n_waves / ceil(n_waves);
55	        // printf("num_splits = %d, eff = %f\n", num_splits, eff);
56	        if (eff > max_efficiency) { max_efficiency = eff; }
57	        efficiency.push_back(eff);
58	    }
59	    for (int num_splits = 1; num_splits <= max_splits; num_splits++) {
60	        if (efficiency[num_splits - 1] >= 0.85 * max_efficiency) {
61	            // printf("num_splits chosen = %d\n", num_splits);
62	            return num_splits;
63	        }
64	    }
65	    return 1;
66	}
