28	template <int Arch, int kHeadDim, int kHeadDimV, int ClusterM, typename Element, typename ElementOut,
29	          bool Is_causal, bool Is_local, bool Has_softcap, bool Varlen, bool PagedKVNonTMA, bool AppendKV, bool HasQv,
30	          bool PackGQA, bool Split, bool V_colmajor, bool Use_one_mma_wg, int kBlockH=1>
31	void run_flash_fwd(Flash_fwd_params &params, cudaStream_t stream) {
32	    static_assert(!(Is_causal && Is_local), "Causal and Local cannot be enabled at the same time");
33	    static_assert(!(AppendKV && V_colmajor), "AppendKV and V_colmajor cannot be enabled at the same time");
34	    static_assert(!(AppendKV && !Varlen), "AppendKV requires Varlen");
35	    static constexpr bool Is_FP8 = cute::is_same_v<Element, cutlass::float_e4m3_t> || cute::is_same_v<Element, cutlass::float_e5m2_t>;
36	    static constexpr bool FP8_TransposeV = Is_FP8 && !V_colmajor;
37	    using ArchTag = std::conditional_t<Arch >= 90, cutlass::arch::Sm90, cutlass::arch::Sm80>;
38	    using ElementS = cutlass::bfloat16_t;
39	
40	    // Can't use structured binding since it's not compatible with constexpr
41	    static constexpr std::tuple<int, int, bool, bool> kBlockMN_RS_IntraWGOverlap = tile_size_fwd_sm90(kHeadDim, kHeadDimV, Is_causal, Is_local, sizeof(Element) /*element_size*/, V_colmajor, PagedKVNonTMA, Has_softcap, Use_one_mma_wg);
42	    static constexpr std::tuple<int, int, int, int, bool> kBlockMN_kNWarps_Stages_RS = tile_size_fwd_sm8x(Arch == 86 || Arch == 89, kHeadDim, kHeadDimV, Is_causal, Is_local, sizeof(Element) /*element_size*/, PagedKVNonTMA, Varlen && Split, Has_softcap, AppendKV);
43	    static constexpr int kBlockM = Arch >= 90 ? std::get<0>(kBlockMN_RS_IntraWGOverlap) : std::get<0>(kBlockMN_kNWarps_Stages_RS);
44	    static constexpr int kBlockN = Arch >= 90 ? std::get<1>(kBlockMN_RS_IntraWGOverlap) : std::get<1>(kBlockMN_kNWarps_Stages_RS);
45	    static constexpr bool MmaPV_is_RS = std::get<2>(kBlockMN_RS_IntraWGOverlap);
46	    static constexpr bool IntraWGOverlap = std::get<3>(kBlockMN_RS_IntraWGOverlap);
47	    static constexpr int kNWarps = std::get<2>(kBlockMN_kNWarps_Stages_RS);
48	    static constexpr int kStages = Arch >= 90 ? 2 : std::get<3>(kBlockMN_kNWarps_Stages_RS);
49	    static constexpr bool Q_in_regs = Arch >= 90 ? false : std::get<4>(kBlockMN_kNWarps_Stages_RS);
50	
51	    using TileShape_MNK = cute::Shape<Int<kBlockM>, Int<kBlockN>, Int<kHeadDim>>;
52	    using TileShape_MNK_PV = cute::Shape<Int<kBlockM>, Int<kHeadDimV>, Int<kBlockN>>;
53	    using ClusterShape = cute::Shape<Int<ClusterM>, _1, _1>;
54	    using CollectiveMainloop = std::conditional_t<
55	        Arch >= 90,
56	        flash::CollectiveMainloopFwdSm90<kStages, ClusterShape, TileShape_MNK, kHeadDimV, Element, float, cutlass::arch::Sm90, Is_causal, Is_local, Has_softcap, Varlen, PagedKVNonTMA, AppendKV, HasQv, MmaPV_is_RS, IntraWGOverlap, PackGQA, Split, V_colmajor, ElementS, kBlockH>,
57	        flash::CollectiveMainloopFwdSm80<kNWarps, kStages, Q_in_regs, TileShape_MNK, kHeadDimV, Element, float, cutlass::arch::Sm80, Is_causal, Is_local, Has_softcap, Varlen, PagedKVNonTMA, AppendKV, PackGQA, Split, ElementS>
58	    >;
59	    using CollectiveEpilogue = flash::CollectiveEpilogueFwd<TileShape_MNK_PV, ClusterShape, ElementOut, ArchTag, CollectiveMainloop::NumMmaThreads, Varlen, PackGQA, Split, FP8_TransposeV, kBlockH>;
60	
61	    static constexpr int NumProducerThreads = Arch >= 90 ? CollectiveMainloop::NumProducerThreads : CollectiveMainloop::NumMmaThreads;
62	    static constexpr bool LPT = Is_causal || Is_local;
63	    // static constexpr bool Sort = !Is_local;
64	     static constexpr bool Sort = false;
65	    using SchedulerPersistent = std::conditional_t<Varlen,
66	        flash::VarlenDynamicPersistentTileScheduler<kBlockM, kBlockN, CollectiveMainloop::NumMmaThreads, NumProducerThreads, Split, PackGQA, Arch >= 90 /*WarpSpecialized*/, LPT, Sort, true /*Prepared*/>,
67	        std::conditional_t<!Is_causal && !Is_local,
68	            flash::StaticPersistentTileScheduler<Split>,
69	            flash::DynamicPersistentTileScheduler<CollectiveMainloop::NumMmaThreads, NumProducerThreads, Split, PackGQA, Arch >= 90 /*WarpSpecialized*/>
70	        >
71	    >;
72	    using SchedulerSingleTile = flash::SingleTileScheduler<Varlen, Split, PackGQA, kBlockM>;
73	    // If Split then we probably don't have enough work for PersistentScheduler to be useful.
74	    // However, if Varlen (e.g., during decode where we have max_seqlens), using PersistentScheduler is better
75	    // since we'll avoid launching a bunch of thread blocks that immediately exit.
76	    // On Sm80, noncausal persistent seems a bit slower.
77	    static constexpr bool UsePersistentScheduler = Arch >= 90 ? !(Split && !Varlen) : ((Is_causal && !Varlen) || (Varlen && Split));
78	    using Scheduler = std::conditional_t<!UsePersistentScheduler, SchedulerSingleTile, SchedulerPersistent>;
79	    using AttnKernel = std::conditional_t<
80	        Arch >= 90,
81	        flash::enable_sm90_or_later<flash::FlashAttnFwdSm90<CollectiveMainloop, CollectiveEpilogue, Scheduler>>,
82	        flash::enable_sm80_to_sm89<flash::FlashAttnFwdSm80<CollectiveMainloop, CollectiveEpilogue, Scheduler>>
83	    >;
84	
85	    bool const is_varlen_q = params.cu_seqlens_q;
86	    bool const is_varlen_k = params.cu_seqlens_k;
87	    bool const is_varlen_k_new = params.cu_seqlens_knew;
88	    int seqlen_q = !is_varlen_q ? params.seqlen_q : params.total_q;
89	    int batch_q = !is_varlen_q ? params.b : 1;
90	    int batch_k = !is_varlen_k ? (params.kv_batch_idx ? params.b_k : params.b) : 1;
91	    typename CollectiveMainloop::StrideV v_strides =
92	        cute::conditional_return<!V_colmajor>(
93	            make_stride(params.v_row_stride, _1{}, params.v_head_stride, !is_varlen_k ? params.v_batch_stride : 0),
94	            make_stride(_1{}, params.v_dim_stride, params.v_head_stride, !is_varlen_k ? params.v_batch_stride : 0));
95	    typename CollectiveMainloop::Arguments mainloop_args {
96	        static_cast<Element const*>(params.q_ptr),
97	        {seqlen_q, params.d, params.h, batch_q},  // shape_Q
98	        {params.q_row_stride, _1{}, params.q_head_stride, !is_varlen_q ? params.q_batch_stride : 0},  // stride_Q
99	        static_cast<Element*>(params.k_ptr),
100	        {!params.page_table ? (!is_varlen_k ? params.seqlen_k : params.total_k) : params.page_size,
101	         params.d, params.h_k, !params.page_table ? batch_k : params.num_pages},  // shape_K
102	        {params.k_row_stride, _1{}, params.k_head_stride, !is_varlen_k ? params.k_batch_stride : 0},  // stride_K
103	        static_cast<Element*>(params.v_ptr),
104	        params.dv,  // headdim_v
105	        v_strides,  // stride_V
106	        static_cast<Element const*>(params.knew_ptr),
107	        {!is_varlen_k_new ? params.seqlen_knew : params.total_knew, params.d, params.h_k, !is_varlen_k_new ? params.b : 1},  // shape_K_new
108	        {params.knew_row_stride, _1{}, params.knew_head_stride, !is_varlen_k_new ? params.knew_batch_stride : 0},  // stride_K_new
109	        static_cast<Element const*>(params.vnew_ptr),
110	        {params.vnew_row_stride, _1{}, params.vnew_head_stride, !is_varlen_k_new ? params.vnew_batch_stride : 0}, // stride_V_new
111	        static_cast<Element const*>(params.qv_ptr),
112	        {params.qv_row_stride, _1{}, params.qv_head_stride, !is_varlen_q ? params.qv_batch_stride : 0},  // stride_Qv
113	        static_cast<Element const*>(params.rotary_cos_ptr),
114	        {params.seqlen_k, params.rotary_dim / 2},  // shape_rotary, the seqlen shape doesn't matter
115	        {params.rotary_dim / 2, _1{}},  // stride_rotary_cos
116	        static_cast<Element const*>(params.rotary_sin_ptr),
117	        {params.rotary_dim / 2, _1{}},  // stride_rotary_sin
118	        params.is_rotary_interleaved,
119	        params.page_table,
120	        // if page_size is not set, avoid dividing by zero
121	        {params.kv_batch_idx ? params.b_k : params.b, !params.page_table ? 0 : params.seqlen_k / params.page_size}, // shape_page_table
122	        {params.page_table_batch_stride, _1{}},  // stride_page_table
123	        params.scale_softmax,
124	        params.q_descale_ptr, params.k_descale_ptr, params.v_descale_ptr,
125	        {params.q_descale_batch_stride, params.q_descale_head_stride},
126	        {params.k_descale_batch_stride, params.k_descale_head_stride},
127	        {params.v_descale_batch_stride, params.v_descale_head_stride},
128	        params.window_size_left, params.window_size_right,
129	        params.softcap,
130	        params.num_splits,
131	        params.kv_batch_idx,
132	        params.cu_seqlens_q, params.cu_seqlens_k, params.cu_seqlens_knew,
133	        params.seqused_q, params.seqused_k,
134	        params.leftpad_k, params.seqlens_rotary,
135	        static_cast<ElementS const*>(params.s_aux_ptr),
136	        params.cp_world_size, params.cp_rank, params.cp_tot_seqused_k
137	    };
138	    typename CollectiveEpilogue::Arguments epilogue_args {
139	        static_cast<ElementOut*>(params.o_ptr),
140	        {seqlen_q, params.dv, params.h, batch_q, params.num_splits},  // shape_O
141	        {params.o_row_stride, _1{}, params.o_head_stride, !is_varlen_q ? params.o_batch_stride : 0, 0}, // stride_O
142	        static_cast<float*>(params.oaccum_ptr),
143	        {params.oaccum_row_stride, _1{}, params.oaccum_head_stride, !is_varlen_q ? params.oaccum_batch_stride : 0, params.oaccum_split_stride}, // stride_O_partial
144	        static_cast<float*>(params.softmax_lse_ptr),
145	        {_1{}, seqlen_q, !is_varlen_q ? params.h * seqlen_q : 0, 0},  // stride_LSE
146	        static_cast<float*>(params.softmax_lseaccum_ptr),
147	        {_1{}, seqlen_q, !is_varlen_q ? params.h * seqlen_q : 0, params.h * seqlen_q * batch_q},  // stride_LSE_partial
148	        params.h_k,
149	        params.cu_seqlens_q, params.seqused_q
150	    };
151	
152	    int qhead_per_khead = !PackGQA ? 1 : cutlass::ceil_div(params.h, params.h_k);
153	    int num_blocks_m = cutlass::ceil_div(params.seqlen_q * qhead_per_khead, get<0>(TileShape_MNK{}));
154	    num_blocks_m = cutlass::round_up(num_blocks_m, size<0>(ClusterShape{}));
155	    typename flash::TileSchedulerArguments scheduler_args {
156	        num_blocks_m, !PackGQA ? params.h : params.h_k, params.b, params.num_splits,
157	        params.h / params.h_k,
158	        params.seqlen_q,
159	        params.seqlen_k, params.d, params.dv, sizeof(Element),
160	        params.tile_count_semaphore, params.cu_seqlens_q, params.seqused_q,
161	        params.num_splits_dynamic_ptr,
162	        params.prepare_seqlen_q_ptr,
163	        params.varlen_batch_idx_ptr,
164	        params.num_nheads_in_l2_ptr,
165	        params.cp_world_size,
166	        params.cp_rank,
167	    };
168	
169	    if (Varlen && !params.skip_scheduler_metadata_computation) {
170	        prepare_varlen_num_blocks(params, stream, PackGQA, kBlockM, kBlockN, Arch >= 90 && params.prepare_varlen_pdl /*enable_pdl*/);
171	        CHECK_CUDA_KERNEL_LAUNCH();
172	    }
173	
174	    int device;
175	    CHECK_CUDA(cudaGetDevice(&device));
176	    typename AttnKernel::Params kernel_params = AttnKernel::to_underlying_arguments({
177	        mainloop_args, epilogue_args, {device, params.num_sm}, scheduler_args
178	    });
179	
180	    dim3 grid_dims = AttnKernel::get_grid_shape(kernel_params);
181	    dim3 block_dims = AttnKernel::get_block_shape();
182	    int smem_size = AttnKernel::SharedStorageSize;
183	    // int smem_size_q = sizeof(decltype((typename CollectiveMainloop::TensorStorage{}).smem_q));
184	    // int smem_size_k = sizeof(decltype((typename CollectiveMainloop::TensorStorage{}).smem_k));
185	    // int smem_size_v = sizeof(decltype((typename CollectiveMainloop::TensorStorage{}).smem_v));
186	    // printf("smem_size = %d, q = %d, k = %d, v = %d\n", smem_size, smem_size_q, smem_size_k, smem_size_v);
187	    // Get the ptr to kernel function.
188	    if constexpr (size(ClusterShape{}) > 1) {
189	        void const* kernel = (void const*) cutlass::device_kernel<AttnKernel>;
190	        if (smem_size >= 48 * 1024) {
191	            CHECK_CUDA(cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_size));
192	        }
193	        dim3 cluster_dims(size<0>(ClusterShape{}), size<1>(ClusterShape{}), size<2>(ClusterShape{}));
194	        cutlass::ClusterLaunchParams launch_params{grid_dims, block_dims, cluster_dims, smem_size, stream};
195	        cutlass::launch_kernel_on_cluster(launch_params, kernel, kernel_params);
196	    } else {
197	        auto kernel = cutlass::device_kernel<AttnKernel>;
198	        if (smem_size >= 48 * 1024) {
199	            CHECK_CUDA(cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_size));
200	        }
201	        // kernel<<<grid_dims, block_dims, smem_size, stream>>>(kernel_params);
202	        cutlass::kernel_launch<AttnKernel>(grid_dims, block_dims, smem_size, stream, kernel_params,
203	                                           Arch >= 90 && Varlen && !params.skip_scheduler_metadata_computation && params.prepare_varlen_pdl /*launch_with_pdl*/);
204	    }
205	    CHECK_CUDA_KERNEL_LAUNCH();
206	}
