208	template<int Arch, typename T, int kHeadDim, int kHeadDimV, bool Split, bool PagedKVNonTMA, bool Has_softcap, bool PackGQA>
209	void run_mha_fwd_(Flash_fwd_params &params, cudaStream_t stream) {
210	    static_assert(sizeof(T) == 2 || sizeof(T) == 1, "Only 16bit and 8bit are supported");
211	    static constexpr bool Is_FP8 = cute::is_same_v<T, cutlass::float_e4m3_t> || cute::is_same_v<T, cutlass::float_e5m2_t>;
212	    using T_out = std::conditional_t<!Is_FP8, T, cutlass::bfloat16_t>;
213	    CAUSAL_LOCAL_SWITCH(params.is_causal, params.is_local, Is_causal, Is_local, [&] {
214	        VCOLMAJOR_SWITCH(params.v_dim_stride != 1, V_colmajor_, [&] {
215	            static constexpr bool V_colmajor = V_colmajor_ && sizeof(T) == 1;
216	            VARLEN_SWITCH(params.cu_seqlens_q || params.cu_seqlens_k || params.seqused_q || params.seqused_k || params.leftpad_k, Varlen, [&] {
217	                BOOL_SWITCH(use_one_mma_wg(params), Use_one_mma_wg_, [&] {
218	                    // Avoid over compiliation by making sure this only get set if it is actually used, i.e. we currently only support one mma wg for 64/128 head dim and hopper
219	                    static constexpr bool Use_one_mma_wg = Use_one_mma_wg_ && Arch >= 90 && (kHeadDim == 128 || kHeadDim == 64) && (kHeadDimV == kHeadDim) && !Is_local;
220	                    // Only needed here to decide if we should use cluster
221	                    static constexpr int kBlockM = Arch >= 90 ? std::get<0>(tile_size_fwd_sm90(kHeadDim, kHeadDimV, Is_causal, Is_local, sizeof(T) /*element_size*/, V_colmajor, PagedKVNonTMA, Has_softcap, Use_one_mma_wg)) : 128;
222	                    static constexpr bool Enable_cluster = Arch == 90 && (sizeof(T) == 2 ? (kHeadDim >= 128) : (kHeadDim == 192)) && !Is_causal && !Is_local && !Split && !PagedKVNonTMA && !Varlen && !Use_one_mma_wg;
223	                    QV_SWITCH(params.qv_ptr, HasQV_, [&] {
224	                        static constexpr bool HasQv = HasQV_ && Arch == 90 && !Is_FP8 && kHeadDim == 64 && kHeadDimV >= 256;
225	                        APPENDKV_SWITCH(params.knew_ptr, AppendKV, [&] {
226	                            // Only use Cluster if number of tiles along seqlen_q is even and not varlen
227	                            CLUSTER_SWITCH(cutlass::ceil_div(params.seqlen_q * (!PackGQA ? 1 : params.h / params.h_k), kBlockM) % 2 == 0, Use_cluster, [&] {
228	                                static constexpr int ClusterM = Enable_cluster && Use_cluster ? 2 : 1;
229	                                int const qhead_per_khead = !PackGQA ? 1 : cutlass::ceil_div(params.h, params.h_k);
230	                                PACK_GQA_BLOCK_SWITCH(qhead_per_khead, kBlockH_, [&] {
231	                                    // Non-unary values of kBlockH can improve GQA perf for specific ratios (4, 8, 16) by enabling TMA for loading Q
232	                                    // Disable for hdim diff, fp16, 1 mma wg or split to shrink build
233	                                    static constexpr int kBlockH = !PackGQA || Arch < 90 || (kHeadDim != kHeadDimV) || cute::is_same_v<T, cutlass::half_t> || Use_one_mma_wg || Split ? 1 : kBlockH_;
234	                                    run_flash_fwd<Arch, kHeadDim, kHeadDimV, ClusterM, T, T_out, Is_causal, Is_local, Has_softcap, Varlen, PagedKVNonTMA, AppendKV && Varlen, HasQv, PackGQA, Split, V_colmajor, Use_one_mma_wg, kBlockH>(params, stream);
235	                                });
236	                            });
237	                        });
238	                    });
239	                });
240	            });
241	        });
242	    });
243	}
