222	template<int NumMmaThreads=2 * cutlass::NumThreadsPerWarpGroup, int NumProducerThreads=cutlass::NumThreadsPerWarp,
223	        bool Split=false, bool PackGQA=false, bool WarpSpecialized=true>
224	class DynamicPersistentTileScheduler {
225	
226	    // This scheduler targets the causal (or local) case where each tile takes different
227	    // amount of time. We use longest-processing-time-first scheduling:
228	    // the longest remaining tile is assigned to the first SM that's free.
229	    // SM indicates they are free by incrementing a semaphore.
230	    // However, we have to make sure K & V still fit into L2 cache, so we perform scheduling
231	    // on "sections" of the head & batch dimension, each section consisting of e.g. 8 heads.
232	    // This is the L2 swizzling part. The size of each section is precomputed based on the
233	    // size of K & V and the L2 cache size.
234	
235	    static_assert(WarpSpecialized || NumProducerThreads == NumMmaThreads);
236	    static constexpr int NumThreads = WarpSpecialized ? NumMmaThreads + NumProducerThreads : NumMmaThreads;
237	
238	public:
239	    using SharedStorage = int;
240	
241	protected:
242	    SharedStorage* const tile_count_smem;
243	
244	public:
245	
246	    // Device side kernel params
247	    struct Params {
248	        int const total_blocks;
249	        cutlass::FastDivmod const m_block_divmod, head_divmod;
250	        cutlass::FastDivmod const l2_minor_divmod, l2_major_divmod;
251	        cutlass::FastDivmod const l2_minor_residual_divmod;
252	        int const num_hb_quotient;
253	        int* const tile_count_semaphore;
254	    };
255	
256	    static Params
257	    to_underlying_arguments(TileSchedulerArguments const& args) {
258	        int const size_one_kv_head = args.seqlen_k * (args.headdim + args.headdim_v) * args.element_size * 2;
259	        int const size_l2 = 32 * 1024 * 1024;  // 32 MB for K & V
260	        // Swizzle is the size of each "section". Round swizzle to a power of 2
261	        // If not PackGQA already, the size of each section can increase by qhead_per_khead
262	        // Need to be careful about the case where only one head will fit
263	        int const swizzle = (size_l2 < size_one_kv_head ? 1 : (1 << cutlass::find_log2(size_l2 / size_one_kv_head))) * (PackGQA ? 1 : args.qhead_per_khead);
264	        // If we're in the last section (called residual), we don't want to divide by
265	        // swizzle. Instead we want to divide by the remainder.
266	        int const num_hb_remainder = (args.num_head * args.num_batch) % swizzle;
267	        int const num_split_blocks = args.num_blocks * (!Split ? 1 : args.num_splits);
268	        // printf("num_split_blocks = %d, num_head = %d, num_batch = %d, swizzle = %d, PackGQA = %d, qhead_per_khead = %d, num_hb_remainder = %d\n", num_split_blocks, args.num_head, args.num_batch, swizzle, int(PackGQA), args.qhead_per_khead, num_hb_remainder);
269	        assert(args.tile_count_semaphore != nullptr);
270	        return {num_split_blocks * args.num_head * args.num_batch,
271	                cutlass::FastDivmod(args.num_blocks), cutlass::FastDivmod(args.num_head),
272	                cutlass::FastDivmod(swizzle), cutlass::FastDivmod(swizzle * num_split_blocks),
273	                // don't divide by 0
274	                cutlass::FastDivmod(num_hb_remainder > 0 ? num_hb_remainder : 1),
275	                (args.num_head * args.num_batch) / swizzle,
276	                args.tile_count_semaphore};
277	    }
278	
279	    static dim3
280	    get_grid_shape(Params const& params, int num_sm) {
281	        return {uint32_t(num_sm)};
282	    }
283	
284	    struct WorkTileInfo {
285	        int tile_idx;
286	
287	        CUTLASS_DEVICE
288	        bool
289	        is_valid(Params const& params) const {
290	            return tile_idx < params.total_blocks;
291	        }
292	
293	        CUTLASS_DEVICE
294	        cute::tuple<int32_t, int32_t, int32_t, int32_t>
295	        get_block_coord(Params const& params) const {
296	            int block, bidh, bidb;
297	            int l2_mod, bidhb, bidhb_residual;
298	            bidhb = params.l2_major_divmod.divmod(l2_mod, tile_idx);
299	            // If we're in the last section (called residual), we don't want to divide by
300	            // swizzle. Instead we want to divide by the remainder.
301	            if (bidhb < params.num_hb_quotient) {
302	                block = params.l2_minor_divmod.divmod(bidhb_residual, l2_mod);
303	            } else {
304	                block = params.l2_minor_residual_divmod.divmod(bidhb_residual, l2_mod);
305	            }
306	            bidb = params.head_divmod.divmod(bidh, bidhb * params.l2_minor_divmod.divisor + bidhb_residual);
307	            int split_idx = 0;
308	            if constexpr (Split) {
309	                split_idx = params.m_block_divmod.divmod(block, block);
310	            }
311	            // Longest-processing-time-first
312	            block = params.m_block_divmod.divisor - 1 - block;
313	            return {block, bidh, bidb, split_idx};
314	        }
315	
316	    };
317	
318	    CUTLASS_DEVICE
319	    DynamicPersistentTileScheduler(SharedStorage* const smem_scheduler) : tile_count_smem(smem_scheduler) {};
320	
321	    template<bool IsProducerWarp=false>
322	    CUTLASS_DEVICE
323	    WorkTileInfo
324	    get_initial_work(Params const& params) const {
325	        return {int(blockIdx.x)};
326	    }
327	
328	    CUTLASS_DEVICE
329	    void
330	    init_consumer() const {
331	        if (WarpSpecialized || cutlass::canonical_warp_idx_sync() > 0) {
332	            flash::named_barrier_arrive(NumThreads, cutlass::arch::ReservedNamedBarriers::StreamkBarrier0 /*id*/);  // TileCountSmemEmpty
333	        }
334	    }
335	
336	    CUTLASS_DEVICE
337	    void
338	    prefetch_next_work(Params const& params, WorkTileInfo& current_work) const {
339	        if (threadIdx.x % NumProducerThreads == 0) {
340	            current_work.tile_idx = atomicAdd(params.tile_count_semaphore, 1) + int(gridDim.x);
341	        }
342	    }
343	
344	    template<bool IsProducerWarp=false>
345	    CUTLASS_DEVICE
346	    WorkTileInfo
347	    get_next_work(Params const& params, WorkTileInfo const& current_work) const {
348	        if constexpr (IsProducerWarp) {
349	            // thread 0 already has the right tile_idx, just need to broadcast to the rest of warp 0
350	            int new_tile_idx = __shfl_sync(0xffffffff, current_work.tile_idx, 0 /*lane*/);
351	            flash::named_barrier_sync(NumThreads, cutlass::arch::ReservedNamedBarriers::StreamkBarrier0 /*id*/);  // TileCountSmemEmpty
352	            if (threadIdx.x % NumProducerThreads == 0) {
353	                *tile_count_smem = current_work.tile_idx;
354	            }
355	            flash::named_barrier_arrive(NumThreads, cutlass::arch::ReservedNamedBarriers::StreamkBarrier1 /*id*/);  // TileCountSmemFull
356	            return {new_tile_idx};
357	        } else {
358	            flash::named_barrier_sync(NumThreads, cutlass::arch::ReservedNamedBarriers::StreamkBarrier1 /*id*/);  // TileCountSmemFull
359	            int tile_idx = *tile_count_smem;
360	            flash::named_barrier_arrive(NumThreads, cutlass::arch::ReservedNamedBarriers::StreamkBarrier0 /*id*/);  // TileCountSmemEmpty
361	            return {tile_idx};
362	        }
363	    }
364	
365	};
366	
367	template<int kBlockM, int kBlockN, int NumMmaThreads=2 * cutlass::NumThreadsPerWarpGroup, int NumProducerThreads=cutlass::NumThreadsPerWarp,
368	         bool Split=false, bool PackGQA=false, bool WarpSpecialized=true, bool LPT = false, bool Sort = false, bool Prepared = true>
369	class VarlenDynamicPersistentTileScheduler {
370	
371	    static_assert(WarpSpecialized || NumProducerThreads == NumMmaThreads);
372	    static constexpr int NumThreads = WarpSpecialized ? NumMmaThreads + NumProducerThreads : NumMmaThreads;
373	
374	public:
375	    using SharedStorage = int4;
376	
377	protected:
378	    SharedStorage* const work_info_smem;
379	
380	public:
381	
382	    // Device side kernel params
383	    struct Params {
384	        int num_head, num_batch;
385	        int const qhead_per_khead;
386	        int const seqlen;
387	        // int const max_kvblocks_in_l2;
388	        cutlass::FastDivmod head_divmod;
389	        cutlass::FastDivmod nsplits_divmod;
390	        int* const tile_count_semaphore;
391	        int const* const cu_seqlens;
392	        int const* const seqused;
393	        int const* const num_splits_dynamic_ptr;
394	        int const* const prepare_seqlen_q_ptr;
395	        int const* const varlen_batch_idx_ptr;
396	        // int const* const num_n_blocks_ptr;
397	        int const* const num_nheads_in_l2_ptr;
398	    };
399	
400	    static Params
401	    to_underlying_arguments(TileSchedulerArguments const& args) {
402	        // If Split, for the purpose of scheduling, we pretend that instead there are
403	        // (args.num_splits * args.num_head) number of heads.
404	        assert(args.tile_count_semaphore != nullptr);
405	        assert(args.num_head < (1 << 16));  // We use the top 16 bits to store num_splits & split_idx
406	        assert(!Split || args.num_splits < (1 << 8)); // We use the top 8 bits to store num_splits
407	        // int const size_l2 = 50 * 1024 * 1024; // 50 MB
408	        // int const size_one_kvblock = kBlockN * (args.headdim + args.headdim_v) * args.element_size;
409	        // int max_kvblocks_in_l2 = size_l2 / size_one_kvblock;
410	        return {args.num_head, args.num_batch,
411	                args.qhead_per_khead, args.seqlen,
412	                // max_kvblocks_in_l2,
413	                cutlass::FastDivmod(args.num_head),
414	                cutlass::FastDivmod(!Split ? 1 : args.num_splits),
415	                args.tile_count_semaphore, args.cu_seqlens, args.seqused,
416	                args.num_splits_dynamic_ptr,
417	                args.prepare_seqlen_q_ptr,
418	                args.varlen_batch_idx_ptr,
419	                // aras.num_n_blocks_ptr,
420	                args.num_nheads_in_l2_ptr};
421	    }
422	
423	    static dim3
424	    get_grid_shape(Params const& params, int num_sm) {
425	        return {uint32_t(num_sm)};
426	    }
427	
428	    struct WorkTileInfo {
429	        int tile_idx, block, bidh, bidb;
430	
431	        CUTLASS_DEVICE
432	        bool
433	        is_valid(Params const& params) const {
434	            // if (blockIdx.x >= 0 && (threadIdx.x == 128 || threadIdx.x == 0)) { printf("blockIdx.x = %d, threadIdx.x = %d, checking valid, bidb = %d, params.num_batch = %d\n", blockIdx.x, threadIdx.x, bidb, params.num_batch); }
435	            return bidb < params.num_batch;
436	        }
437	
438	        CUTLASS_DEVICE
439	        cute::tuple<int32_t, int32_t, int32_t, int32_t>
440	        get_block_coord(Params const& params) const {
441	            auto get_actual_batch = [&](int virtual_batch) {
442	                if constexpr(Prepared && Sort) {
443	                    return params.varlen_batch_idx_ptr[virtual_batch];
444	                } else {
445	                    return virtual_batch;
446	                }
447	            };
448	            if constexpr (!Split) {
449	                return {block, bidh, get_actual_batch(bidb), 0 /*split_idx*/};
450	            } else {
451	                // the top 8 bits of bidh store num_splits and the next 8 bits store split_idx
452	                // reinterpret_cast to uint32_t to make sure we're not doing sign extension when we shift
453	                uint32_t bidh_packed = reinterpret_cast<uint32_t const&>(bidh);
454	                uint32_t bidh_actual_u = bidh_packed & 0x0000FFFF;
455	                int bidh_actual = reinterpret_cast<int&>(bidh_actual_u);
456	                // Use the top 16 bits of split_idx to store num_splits and the next 16 bits to store split_idx
457	                uint32_t split_idx_u = ((bidh_packed & 0x00FF0000) >> 16) + ((bidh_packed & 0xFF000000) >> 8);
458	                int split_idx = reinterpret_cast<int&>(split_idx_u);
459	                // int bidh_actual = params.nsplits_divmod.divmod(split_idx, bidh);
460	                // if (threadIdx.x == 128) {
461	                //     printf("blockIdx.x = %d, bidb = %d, bidh = %d, bidh_actual = %d, split_idx = %d\n", blockIdx.x, bidb, bidh, bidh_actual, split_idx);
462	                // }
463	                return {block, bidh_actual, get_actual_batch(bidb), split_idx};
464	            }
465	        }
466	    };
467	
468	    CUTLASS_DEVICE
469	    VarlenDynamicPersistentTileScheduler(SharedStorage* const smem_scheduler) : work_info_smem(smem_scheduler) {};
470	
471	    CUTLASS_DEVICE
472	    WorkTileInfo
473	    tile_idx_to_work_tile(Params const& params, int next_tile_idx, WorkTileInfo const& current_work) const {
474	        int lane = threadIdx.x % cutlass::NumThreadsPerWarp;
475	        auto get_num_m_blocks = [&] (int bidb_start) {
476	            int batch_idx = lane + bidb_start;
477	            if constexpr (Prepared) {
478	                return batch_idx < params.num_batch && lane < cutlass::NumThreadsPerWarp - 1
479	                    ? cute::ceil_div(params.prepare_seqlen_q_ptr[batch_idx], kBlockM) : 0;
480	            } else {
481	                int seqlen = params.seqlen * (!PackGQA ? 1 : params.qhead_per_khead);
482	                if (seqlen > kBlockM) {
483	                    if (params.seqused) {
484	                        seqlen = batch_idx < params.num_batch ? params.seqused[batch_idx] : 0;
485	                    } else if (params.cu_seqlens) {
486	                        int cur_cu_seqlen = batch_idx <= params.num_batch ? params.cu_seqlens[batch_idx] : 0;
487	                        int next_cu_seqlen = __shfl_down_sync(0xffffffff, cur_cu_seqlen, 1);
488	                        seqlen = next_cu_seqlen - cur_cu_seqlen;
489	                    } else {
490	                        seqlen = params.seqlen;
491	                    }
492	                    if constexpr (PackGQA) { seqlen *= params.qhead_per_khead; }
493	                }
494	                return batch_idx < params.num_batch && lane < cutlass::NumThreadsPerWarp - 1
495	                    ? cute::ceil_div(seqlen, kBlockM) : 0;
496	            }
497	        };
498	
499	        auto get_num_splits = [&] (int bidb_start) {
500	            int batch_idx = lane + bidb_start;
501	            bool is_valid = batch_idx < params.num_batch && lane < cutlass::NumThreadsPerWarp - 1;
502	            if constexpr (!Split) {
503	                return is_valid ? 1 : 0;
504	            } else if constexpr(Prepared) {
505	                return is_valid ? params.num_splits_dynamic_ptr[batch_idx] : 0;
506	            } else {
507	                return is_valid ? params.nsplits_divmod.divisor : 0;
508	            }
509	        };
510	
511	        int num_m_blocks = get_num_m_blocks(current_work.bidb);  // Different for each lane
512	        int num_splits = get_num_splits(current_work.bidb);
513	        int num_split_m_blocks = !Split ? num_m_blocks : num_m_blocks * num_splits;
514	        // Cumulative number of blocks for the next 31 batches
515	        int num_m_blocks_cumulative = warp_prefix_sum(num_split_m_blocks);
516	        // Total number of blocks for the next 31 batches
517	        int m_blocks_in_group = __shfl_sync(0xffffffff, num_m_blocks_cumulative, cutlass::NumThreadsPerWarp - 1);
518	        // Only the lower 16 bits are the actual bidh
519	        // int current_bidh = !Split ? current_work.bidh : (current_work.bidh & 0x0000FFFF);
520	        // int group_end_tile = current_work.tile_idx - current_work.block - current_bidh * __shfl_sync(0xffffffff, num_split_m_blocks, 0 /*lane*/) + m_blocks_in_group * params.num_head;  // Same for all lanes
521	        // if constexpr (Split) {
522	        //     int current_split_idx = (current_work.bidh & 0x00FF0000) >> 16;
523	        //     group_end_tile -= current_split_idx * __shfl_sync(0xffffffff, num_m_blocks, 0 /*lane*/);
524	        // }
525	        // NEW: current_work.tile_idx holds group_start_tile for starting batch
526	        int group_end_tile = current_work.tile_idx + m_blocks_in_group * params.num_head;  // Same for all lanes
527	        int bidb = current_work.bidb;
528	        // if (blockIdx.x <= 9 && threadIdx.x == 0) {
529	        //     printf("Before while, blockIdx.x = %d, threadIdx.x = %d, bidb = %d, num_m_blocks = %d, next_tile_idx = %d, cur tile_idx = %d, cur block = %d, cur bidh = %d, num_split_m_blocks = %d, group_end_tile = %d, m_blocks_in_group = %d\n", blockIdx.x, threadIdx.x, current_work.bidb, num_m_blocks, next_tile_idx, current_work.tile_idx, current_work.block, current_bidh, num_split_m_blocks, group_end_tile, m_blocks_in_group);
530	        // }
531	        // if (threadIdx.x == 0 && blockIdx.x == 0) { printf("tile_idx = %d, group_end_tile = %d, num_m_blocks_cumulative = %d, m_blocks_in_group = %d\n", current_work.tile_idx, group_end_tile, num_m_blocks_cumulative, m_blocks_in_group); }
532	        while (group_end_tile <= next_tile_idx) {
533	            bidb += cutlass::NumThreadsPerWarp - 1;
534	            if (bidb >= params.num_batch) {
535	                // if (blockIdx.x <= 9 && threadIdx.x == 0) {
536	                //     printf("Returning early, blockIdx.x = %d, threadIdx.x = %d, bidb = %d, num_m_blocks = %d, next_tile_idx = %d, group_end_tile = %d, m_blocks_in_group = %d\n", blockIdx.x, threadIdx.x, bidb, num_m_blocks, next_tile_idx, group_end_tile, m_blocks_in_group);
537	                // }
538	                return {next_tile_idx, 0, 0, params.num_batch};
539	            }
540	            num_m_blocks = get_num_m_blocks(bidb);
541	            num_splits = get_num_splits(bidb);
542	            num_split_m_blocks = !Split ? num_m_blocks : num_m_blocks * num_splits;
543	            num_m_blocks_cumulative = warp_prefix_sum(num_split_m_blocks);
544	            m_blocks_in_group = __shfl_sync(0xffffffff, num_m_blocks_cumulative, cutlass::NumThreadsPerWarp - 1);
545	            group_end_tile += m_blocks_in_group * params.num_head;
546	            // if (blockIdx.x <= 9 && threadIdx.x == 0) {
547	            //     printf("Bottom of while, blockIdx.x = %d, threadIdx.x = %d, bidb = %d, num_m_blocks = %d, next_tile_idx = %d, group_end_tile = %d, m_blocks_in_group = %d\n", blockIdx.x, threadIdx.x, bidb, num_m_blocks, next_tile_idx, group_end_tile, m_blocks_in_group);
548	            // }
549	        }
550	        int group_start_tile = group_end_tile - m_blocks_in_group * params.num_head;
551	        // The next problem to process is the first one that does not have ending tile position
552	        // that is greater than or equal to tile index.
553	        int batch_idx_in_group = __popc(__ballot_sync(0xffffffff, group_start_tile + num_m_blocks_cumulative * params.num_head <= next_tile_idx));
554	        // if (threadIdx.x == 31 || threadIdx.x == 0) { printf("blockIdx.x = %d, tidx %d, group_start_tile = %d, num_m_blocks_cumulative = %d, num_head = %d, next_tile_idx = %d, ballot = %x, batch_idx_in_group = %d\n", blockIdx.x, threadIdx.x, group_start_tile, num_m_blocks_cumulative, params.num_head, next_tile_idx, tmp, batch_idx_in_group); }
555	        bidb += batch_idx_in_group;
556	        num_m_blocks = __shfl_sync(0xffffffff, num_m_blocks, batch_idx_in_group);
557	        if constexpr (Split) { num_splits = __shfl_sync(0xffffffff, num_splits, batch_idx_in_group); }
558	        group_start_tile += (batch_idx_in_group == 0 ? 0 : __shfl_sync(0xffffffff, num_m_blocks_cumulative, batch_idx_in_group - 1)) * params.num_head;
559	        int mh_block = next_tile_idx - group_start_tile;
560	        int block, bidh;
561	        if constexpr (LPT) {
562	            if (!Split || num_splits == 1) {
563	                // NOTE: code for computing nheads_in_l2 directly left as reference
564	                // int num_n_blocks = params.num_n_blocks_ptr ? params.num_n_blocks_ptr[bidb] : num_m_blocks;
565	                // auto find_log2_floor = [&](int n) { return 31 - cutlass::clz(n); };
566	                // int nheads_in_l2 = params.max_kvblocks_in_l2 < num_n_blocks
567	                //     ? 1 : 1 << find_log2_floor(params.max_kvblocks_in_l2 / num_n_blocks);
568	                // if constexpr (!PackGQA) { nheads_in_l2 *= params.qhead_per_khead; }
569	                // nheads_in_l2 = min(nheads_in_l2, params.num_head);
570	                auto get_nheads_in_l2 = [&](int batch_idx) {
571	                    if constexpr(Prepared) {
572	                        return params.num_nheads_in_l2_ptr[batch_idx];
573	                    } else {
574	                        return !PackGQA ? params.qhead_per_khead : 1;
575	                    }
576	                };
577	                int nheads_in_l2 = get_nheads_in_l2(bidb);
578	                int mh_in_l2 = nheads_in_l2 * num_m_blocks;
579	                int section_idx = mh_block / mh_in_l2;
580	                int l2_mod = mh_block - section_idx * mh_in_l2;
581	                // tail section
582	                int nheads_remainder = params.num_head - section_idx * nheads_in_l2;
583	                int nheads_in_this_section = nheads_in_l2 <= nheads_remainder ? nheads_in_l2 : nheads_remainder;
584	                block = l2_mod / nheads_in_this_section;
585	                int bidh_residual = l2_mod - block * nheads_in_this_section;
586	                bidh = section_idx * nheads_in_l2 + bidh_residual;
587	                if constexpr(Split) {
588	                    // remember to set num_splits = 1 in work tile
589	                    uint32_t bidh_packed = reinterpret_cast<uint32_t&>(bidh) + (reinterpret_cast<uint32_t&>(num_splits) << 24);
590	                    bidh = reinterpret_cast<int&>(bidh_packed);
591	                }
592	            } else {
593	                // NOTE: leave traverse heads first version for reference
594	                // block = params.head_divmod.divmod(bidh, mh_block);
595	                // if constexpr (Split) {
596	                //     int split_idx = block / num_m_blocks;
597	                //     block = block - split_idx * num_m_blocks;
598	                //     uint32_t bidh_packed = reinterpret_cast<uint32_t&>(bidh) + (reinterpret_cast<uint32_t&>(split_idx) << 16) + (reinterpret_cast<uint32_t&>(num_splits) << 24);
599	                //     bidh = reinterpret_cast<int&>(bidh_packed);
600	                // }
601	                bidh = mh_block / num_m_blocks;
602	                block = mh_block - bidh * num_m_blocks;
603	                if constexpr (Split) {
604	                    int bidh_actual = bidh / num_splits;
605	                    int split_idx = bidh - bidh_actual * num_splits;
606	                    uint32_t bidh_packed = reinterpret_cast<uint32_t&>(bidh_actual) + (reinterpret_cast<uint32_t&>(split_idx) << 16) + (reinterpret_cast<uint32_t&>(num_splits) << 24);
607	                    bidh = reinterpret_cast<int&>(bidh_packed);
608	                }
609	            }
610	            block = num_m_blocks - 1 - block;
611	        } else {
612	            bidh = mh_block / num_m_blocks;
613	            block = mh_block - bidh * num_m_blocks;
614	            if constexpr (Split) {
615	                int bidh_actual = bidh / num_splits;
616	                int split_idx = bidh - bidh_actual * num_splits;
617	                // TODO: idk why this gives wrong answer nondeterministically
618	                // int bidh_actual, split_idx;
619	                // split_idx = params.head_divmod.divmod(bidh_actual, bidh);
620	                // Use the top 8 bits to store num_splits and the next 8 bits to store split_idx
621	                // reinterpret_cast to uint32_t to make sure we're not doing sign extension when we shift
622	                uint32_t bidh_packed = reinterpret_cast<uint32_t&>(bidh_actual) + (reinterpret_cast<uint32_t&>(split_idx) << 16) + (reinterpret_cast<uint32_t&>(num_splits) << 24);
623	                // if (threadIdx.x == 0) {
624	                //     printf("blockIdx.x = %d, group_start_tiled = %d, bidb = %d, batch_idx_in_group = %d, mh_block = %d, num_m_blocks = %d, bidh = %d, bidh_actual = %d, split_idx = %d, num_splits = %d, bidh_packed = %d\n", blockIdx.x, group_start_tile, bidb, batch_idx_in_group, mh_block, num_m_blocks, bidh, bidh_actual, split_idx, num_splits, bidh_packed);
625	                // }
626	                bidh = reinterpret_cast<int&>(bidh_packed);
627	            }
628	            // if (blockIdx.x <= 9 && threadIdx.x == 0) {
629	            //     printf("Before returning, blockIdx.x = %d, threadIdx.x = %d, group_start_tile = %d, batch_idx_in_group = %d, bidb = %d, num_m_blocks = %d, next_tile_idx = %d, group_end_tile = %d, m_blocks_in_group = %d, mh_block = %d, bidh = %d, block = %d\n", blockIdx.x, threadIdx.x, group_start_tile, batch_idx_in_group, bidb, num_m_blocks, next_tile_idx, group_end_tile, m_blocks_in_group, mh_block, bidh, block);
630	            // }
631	        }
632	        return {group_start_tile, block, bidh, bidb};
633	    }
634	
635	    template<bool IsProducerWarp=false>
636	    CUTLASS_DEVICE
637	    WorkTileInfo
638	    get_initial_work(Params const& params) const {
639	        if constexpr (IsProducerWarp) {
640	            WorkTileInfo work_info = tile_idx_to_work_tile(params, int(blockIdx.x), {0, 0, 0, 0});
641	            if (threadIdx.x % cutlass::NumThreadsPerWarp == 0) {
642	                *work_info_smem = make_int4(work_info.tile_idx, work_info.block, work_info.bidh, work_info.bidb);
643	            }
644	            flash::named_barrier_arrive(NumThreads, cutlass::arch::ReservedNamedBarriers::StreamkBarrier1 /*id*/);  // TileCountSmemFull
645	            return work_info;
646	        } else {
647	            return get_next_work<false>(params, {0, 0, 0, 0});
648	        }
649	    }
650	
651	    CUTLASS_DEVICE
652	    void
653	    init_consumer() const {
654	        // Don't arrive at the TileCountSmemEmpty barrier here, because get_initial_work will do that
655	    }
656	
657	    CUTLASS_DEVICE
658	    void
659	    prefetch_next_work(Params const& params, WorkTileInfo& current_work) const {
660	        if (threadIdx.x % NumProducerThreads == 0) {
661	            current_work.tile_idx = atomicAdd(params.tile_count_semaphore, 1) + int(gridDim.x);
662	        }
663	    }
664	
665	    template<bool IsProducerWarp=false>
666	    CUTLASS_DEVICE
667	    WorkTileInfo
668	    get_next_work(Params const& params, WorkTileInfo const& current_work) const {
669	        if constexpr (IsProducerWarp) {
670	            // thread 0 has the next tile_idx, just need to broadcast to the rest of warp 0
671	            int new_tile_idx = __shfl_sync(0xffffffff, current_work.tile_idx, 0 /*lane*/);
672	            WorkTileInfo work_info = {__shfl_sync(0xffffffff, current_work.tile_idx, 1 /*lane*/), current_work.block, current_work.bidh, current_work.bidb};
673	            work_info = tile_idx_to_work_tile(params, new_tile_idx, work_info);
674	            flash::named_barrier_sync(NumThreads, cutlass::arch::ReservedNamedBarriers::StreamkBarrier0 /*id*/);  // TileCountSmemEmpty
675	            if (threadIdx.x % cutlass::NumThreadsPerWarp == 0) {
676	                *work_info_smem = make_int4(work_info.tile_idx, work_info.block, work_info.bidh, work_info.bidb);
677	            }
678	            flash::named_barrier_arrive(NumThreads, cutlass::arch::ReservedNamedBarriers::StreamkBarrier1 /*id*/);  // TileCountSmemFull
679	            return work_info;
680	        } else {
681	            flash::named_barrier_sync(NumThreads, cutlass::arch::ReservedNamedBarriers::StreamkBarrier1 /*id*/);  // TileCountSmemFull
682	            int4 work_info = *work_info_smem;
683	            flash::named_barrier_arrive(NumThreads, cutlass::arch::ReservedNamedBarriers::StreamkBarrier0 /*id*/);  // TileCountSmemEmpty
684	            return WorkTileInfo{work_info.x, work_info.y, work_info.z, work_info.w};
685	        }
686	    }
687	
688	};
689	
690	} // flash
