28	class FlashAttnFwdSm90 {
29	
30	public:
31	
32	    // Type Aliases
33	    using CollectiveMainloop = CollectiveMainloop_;
34	    using CollectiveEpilogue = CollectiveEpilogue_;
35	    static constexpr bool Is_causal = CollectiveMainloop::Is_causal;
36	    static constexpr bool Is_local = CollectiveMainloop::Is_local;
37	    static_assert(CollectiveMainloop::Varlen == CollectiveEpilogue::Varlen);
38	    static constexpr bool Has_softcap = CollectiveMainloop::Has_softcap;
39	    static constexpr bool Varlen = CollectiveMainloop::Varlen;
40	    static constexpr bool Split = CollectiveMainloop::Split;
41	    static constexpr bool Is_FP8 = CollectiveMainloop::Is_FP8;
42	    static constexpr bool Transpose_V = CollectiveMainloop::Transpose_V;
43	    static constexpr bool AppendKV = CollectiveMainloop::AppendKV;
44	    static constexpr bool HasQv = CollectiveMainloop::HasQv;
45	    static constexpr bool Use_TMA_Q = CollectiveMainloop::Use_TMA_Q;
46	    static constexpr bool Use_TMA_KV = CollectiveMainloop::Use_TMA_KV;
47	    static constexpr bool Use_TMA_O = CollectiveEpilogue::Use_TMA_O;
48	    static constexpr bool PackGQA = CollectiveMainloop::PackGQA;
49	    static constexpr int NumProducerThreads = CollectiveMainloop::NumProducerThreads;
50	    static constexpr bool SameHeadDim = CollectiveMainloop::SameHeadDim;
51	    static constexpr bool LargeHeadDimV = CollectiveMainloop::LargeHeadDimV;
52	    static_assert(CollectiveMainloop::LargeHeadDimV == CollectiveEpilogue::LargeHeadDimV);
53	    using SeqlenInfo_t = typename CollectiveMainloop::SeqlenInfo_t;
54	
55	    using SmemLayoutSAux = typename CollectiveMainloop::SmemLayoutSAux;
56	
57	    // Mainloop derived types
58	    using TileShape_MNK_PV = typename CollectiveMainloop::TileShape_MNK_PV;
59	    using TiledMmaPV = typename CollectiveMainloop::TiledMmaPV;
60	    using ArchTag = typename CollectiveMainloop::ArchTag;
61	    using ClusterShape = typename CollectiveMainloop::ClusterShape;
62	    using MainloopArguments = typename CollectiveMainloop::Arguments;
63	    using MainloopParams = typename CollectiveMainloop::Params;
64	    using BarrierQ = std::conditional_t<Use_TMA_Q, cutlass::arch::ClusterTransactionBarrier, cutlass::arch::ClusterBarrier>;
65	
66	    // Epilogue derived types
67	    using EpilogueArguments = typename CollectiveEpilogue::Arguments;
68	    using EpilogueParams = typename CollectiveEpilogue::Params;
69	
70	    static_assert(ArchTag::kMinComputeCapability >= 90);
71	
72	    using TileScheduler = TileScheduler_;
73	    using TileSchedulerArguments = typename flash::TileSchedulerArguments;
74	    using TileSchedulerParams = typename TileScheduler::Params;
75	
76	    static constexpr uint32_t NumLoadWarpGroups = 1;
77	    static constexpr uint32_t NumMmaWarpGroups = CUTE_STATIC_V(size(TiledMmaPV{})) / cutlass::NumThreadsPerWarpGroup;
78	    static constexpr uint32_t MaxThreadsPerBlock = CUTE_STATIC_V(size(TiledMmaPV{})) + (NumLoadWarpGroups * cutlass::NumThreadsPerWarpGroup);
79	    static constexpr uint32_t MinBlocksPerMultiprocessor = 1;
80	    static_assert(NumMmaWarpGroups == 1 || NumMmaWarpGroups == 2 || NumMmaWarpGroups == 3);
81	
82	    /// Register requirement for Load and Math WGs
83	    // If we use cp.async to load K and V, we need more registers for the producer WG.
84	    // If we use varlen, we would like more registers for the varlen dynamic persistent scheduler in producer WG, but can only donate sometimes.
85	    static constexpr bool ExtraProducerRegsForVarlen = Varlen && !Is_FP8 && (get<1>(TileShape_MNK_PV{}) == 128 || get<1>(TileShape_MNK_PV{}) == 192);
86	    static constexpr uint32_t LoadRegisterRequirement = NumMmaWarpGroups == 1 ? 56 : (NumMmaWarpGroups == 2 ? (Use_TMA_KV && !ExtraProducerRegsForVarlen ? 24 : 40) : 32);
87	    static constexpr uint32_t MmaRegisterRequirement = NumMmaWarpGroups == 1 ? 256 : (NumMmaWarpGroups == 2 ? (Use_TMA_KV && !ExtraProducerRegsForVarlen ? 240 : 232) : 160);
88	    // If you want to print from the producer warp, you'd need to increase the number of registers
89	    // Otherwise you'll get CUDA error.
90	    // static constexpr uint32_t LoadRegisterRequirement = 40;
91	    // static constexpr uint32_t MmaRegisterRequirement = NumMmaWarpGroups == 2 ? 232 : 152;
92	
93	    // Kernel level shared memory storage
94	    // We overlap the shared memory for the mainloop and epilogue. However, we only want smem_o to overlap with smem_v
95	    // and nothing else, so we'll pad in case sizeof(smem_o) > sizeof(smem_v).
96	    static constexpr int mainloop_smem_padding_ = int(sizeof(typename CollectiveEpilogue::TensorStorage)) - int(sizeof(decltype((typename CollectiveMainloop::TensorStorage{}).smem_v)));
97	    static constexpr int mainloop_smem_padding = mainloop_smem_padding_ < 0 ? 0 : mainloop_smem_padding_;
98	    struct SharedStorage {
99	        struct TensorStorage : cute::aligned_struct<128, _1> {
100	            union {
101	                struct {
102	                    cute::array<uint32_t, mainloop_smem_padding / sizeof(uint32_t)> padding_;
103	                    typename CollectiveMainloop::TensorStorage mainloop;
104	                };
105	                // We want smem_o to line up with the start of smem_v
106	                typename CollectiveEpilogue::TensorStorage epilogue;
107	            };
108	        } tensors;
109	        struct PipelineStorage : cute::aligned_struct<16, _1> {
110	            alignas(16) BarrierQ barrier_Q;
111	            alignas(16) BarrierQ barrier_Qv;
112	            alignas(16) cutlass::arch::ClusterBarrier barrier_O;
113	            alignas(16) typename CollectiveMainloop::MainloopPipelineK::SharedStorage pipeline_k;
114	            alignas(16) typename CollectiveMainloop::MainloopPipelineV::SharedStorage pipeline_v;
115	            alignas(16) typename CollectiveMainloop::MainloopPipelineVt::SharedStorage pipeline_vt;
116	            alignas(16) typename CollectiveMainloop::MainloopPipelineKVNew::SharedStorage pipeline_k_new;
117	            alignas(16) typename CollectiveMainloop::MainloopPipelineKVNew::SharedStorage pipeline_v_new;
118	            alignas(16) typename TileScheduler::SharedStorage smem_scheduler;
119	        } pipelines;
120	
121	    };
122	
123	    static constexpr int SharedStorageSize = sizeof(SharedStorage);
124	
125	    // Device side arguments
126	    struct Arguments {
127	        MainloopArguments mainloop{};
128	        EpilogueArguments epilogue{};
129	        cutlass::KernelHardwareInfo hw_info{};
130	        TileSchedulerArguments scheduler{};
131	    };
132	
133	    // Kernel entry point API
134	    struct Params {
135	        MainloopParams mainloop{};
136	        EpilogueParams epilogue{};
137	        cutlass::KernelHardwareInfo hw_info{};
138	        TileSchedulerParams scheduler{};
139	    };
140	
141	    //
142	    // Methods
143	    //
144	
145	    // Convert to underlying arguments. In this case, a simple copy for the aliased type.
146	    static
147	    Params
148	    to_underlying_arguments(Arguments const& args) {
149	        CUTLASS_TRACE_HOST("to_underlying_arguments():");
150	
151	        // Get SM count if needed, otherwise use user supplied SM count
152	        int sm_count = args.hw_info.sm_count;
153	        if (sm_count <= 0) {
154	            CUTLASS_TRACE_HOST("  WARNING: Arguments do not include a valid SM count.\n"
155	                "  For optimal performance, populate the arguments KernelHardwareInfo struct with the SM count.");
156	            sm_count = cutlass::KernelHardwareInfo::query_device_multiprocessor_count(args.hw_info.device_id);
157	        }
158	
159	        CUTLASS_TRACE_HOST("to_underlying_arguments(): Setting persistent grid SM count to " << sm_count);
160	
161	        cutlass::KernelHardwareInfo hw_info{args.hw_info.device_id, sm_count};
162	        return {
163	            CollectiveMainloop::to_underlying_arguments(args.mainloop),
164	            CollectiveEpilogue::to_underlying_arguments(args.epilogue),
165	            hw_info,
166	            TileScheduler::to_underlying_arguments(args.scheduler)
167	        };
168	    }
169	
170	    // Computes the kernel launch grid shape based on runtime parameters
171	    static dim3
172	    get_grid_shape(Params const& params) {
173	        return TileScheduler::get_grid_shape(params.scheduler, params.hw_info.sm_count);
174	    }
175	
176	    static dim3
177	    get_block_shape() {
178	        return dim3(MaxThreadsPerBlock, 1, 1);
179	    }
180	
181	    CUTLASS_DEVICE
182	    void
183	    operator()(Params const& params, char* smem_buf) {
184	
185	        static constexpr int NumMmaThreads = NumMmaWarpGroups * cutlass::NumThreadsPerWarpGroup;
186	        static constexpr int MmaThreadOffset = NumLoadWarpGroups * cutlass::NumThreadsPerWarpGroup;
187	        static constexpr int kBlockM = get<0>(TileShape_MNK_PV{});
188	
189	        using MainloopPipelineK = typename CollectiveMainloop::MainloopPipelineK;
190	        using MainloopPipelineV = typename CollectiveMainloop::MainloopPipelineV;
191	        using MainloopPipelineVt = typename CollectiveMainloop::MainloopPipelineVt;
192	        using MainloopPipelineKVNew = typename CollectiveMainloop::MainloopPipelineKVNew;
193	        using PipelineState = typename CollectiveMainloop::PipelineState;
194	        using PipelineParamsK = typename MainloopPipelineK::Params;
195	        using PipelineParamsV = typename MainloopPipelineV::Params;
196	        using PipelineParamsVt = typename MainloopPipelineVt::Params;
197	        using PipelineParamsKVNew = typename MainloopPipelineKVNew::Params;
198	
199	        SharedStorage& shared_storage = *reinterpret_cast<SharedStorage*>(smem_buf);
200	
201	        int const lane_predicate = cute::elect_one_sync();
202	        int const warp_idx = cutlass::canonical_warp_idx_sync();
203	
204	        // Issue Tma Descriptor Prefetch from a single thread
205	        if (warp_idx == 0 && lane_predicate) {
206	            CollectiveMainloop::prefetch_tma_descriptors(params.mainloop);
207	            CollectiveEpilogue::prefetch_tma_descriptors(params.epilogue);
208	        }
209	
210	        // Obtain warp index
211	        int const warp_group_thread_idx = threadIdx.x % cutlass::NumThreadsPerWarpGroup;
212	        int warp_group_idx = cutlass::canonical_warp_group_idx();
213	
214	        if (warp_idx == 0 && lane_predicate) {
215	            shared_storage.pipelines.barrier_Q.init(Use_TMA_Q ? 1 : NumProducerThreads /*numThreads*/);
216	            if constexpr (HasQv) {
217	                shared_storage.pipelines.barrier_Qv.init(Use_TMA_Q ? 1 : NumProducerThreads /*numThreads*/);
218	            }
219	            shared_storage.pipelines.barrier_O.init(size(ClusterShape{}) * (Use_TMA_O ? 1 : NumMmaThreads) /*numThreads*/);
220	        }
221	
222	        // We're counting on pipeline_k to call cutlass::arch::fence_barrier_init();
223	        PipelineParamsK pipeline_params_k;
224	        pipeline_params_k.role = warp_group_idx == 0
225	            ? MainloopPipelineK::ThreadCategory::Producer
226	            : MainloopPipelineK::ThreadCategory::Consumer;
227	        if constexpr (Use_TMA_KV) {
228	            pipeline_params_k.transaction_bytes = CollectiveMainloop::TmaTransactionBytesK;
229	            pipeline_params_k.is_leader = warp_group_thread_idx == 0;
230	            pipeline_params_k.num_consumers = !LargeHeadDimV ? NumMmaThreads : cutlass::NumThreadsPerWarpGroup;
231	        } else {
232	            pipeline_params_k.consumer_arv_count = !LargeHeadDimV ? NumMmaThreads : cutlass::NumThreadsPerWarpGroup;
233	            pipeline_params_k.producer_arv_count = NumProducerThreads;
234	        }
235	
236	        static_assert(is_same_v<PipelineParamsK, PipelineParamsVt>);
237	        PipelineParamsVt pipeline_params_vt = pipeline_params_k;
238	        if constexpr (Use_TMA_KV && !SameHeadDim) {
239	            pipeline_params_vt.transaction_bytes = CollectiveMainloop::TmaTransactionBytesV;
240	            if constexpr (LargeHeadDimV) { pipeline_params_vt.num_consumers = NumMmaThreads; }
241	        } else {
242	            if constexpr (LargeHeadDimV) { pipeline_params_vt.consumer_arv_count = NumMmaThreads; }
243	        }
244	
245	        MainloopPipelineK pipeline_k = [&] {
246	            if constexpr (Use_TMA_KV) {
247	                return MainloopPipelineK(shared_storage.pipelines.pipeline_k, pipeline_params_k, ClusterShape{});
248	            } else {
249	                return MainloopPipelineK(shared_storage.pipelines.pipeline_k, pipeline_params_k);
250	            }
251	        }();
252	        // MainloopPipelineV pipeline_v(shared_storage.pipelines.pipeline_v, pipeline_params_v, ClusterShape{});
253	        MainloopPipelineV pipeline_v = [&] {
254	            if constexpr (!Transpose_V) {
255	                static_assert(is_same_v<PipelineParamsK, PipelineParamsV>);
256	                if constexpr (Use_TMA_KV) {
257	                    return MainloopPipelineV(shared_storage.pipelines.pipeline_v, pipeline_params_vt, ClusterShape{});
258	                } else {
259	                    return MainloopPipelineV(shared_storage.pipelines.pipeline_v, pipeline_params_vt);
260	                }
261	            } else {
262	                PipelineParamsV pipeline_params_v;
263	                pipeline_params_v.role = warp_group_idx == 0
264	                    ? MainloopPipelineV::ThreadCategory::Producer
265	                    : MainloopPipelineV::ThreadCategory::Consumer;
266	                pipeline_params_v.producer_arv_count = NumProducerThreads;
267	                pipeline_params_v.consumer_arv_count = NumMmaThreads;
268	                return MainloopPipelineV(shared_storage.pipelines.pipeline_v, pipeline_params_v);
269	            }
270	        }();
271	        // If we need to transpose V (e.g. FP8 and V is row-major), we use pipeline_vt for the TMA, then
272	        // the producer WG will read from pipeline_vt and write to pipeline_v.
273	        // If we don't need to transpose V, we use pipeline_v for the TMA, and pipeline_vt won't be used.
274	        // Technically for pipeline_params_vt, warp0 of WG0 is the producer and all of WG0 are consumers.
275	        // However, the thread role isn't used in the pipeline implementation.
276	        MainloopPipelineVt pipeline_vt = [&] {
277	            if constexpr (Use_TMA_KV) {
278	                pipeline_params_vt.num_consumers = NumProducerThreads; // TMA_V is only consumed by the producer WG
279	                return MainloopPipelineVt(shared_storage.pipelines.pipeline_vt, pipeline_params_vt, ClusterShape{});
280	            } else {
281	                pipeline_params_vt.consumer_arv_count = NumProducerThreads; // TMA_V is only consumed by the producer WG
282	                return MainloopPipelineVt(shared_storage.pipelines.pipeline_vt, pipeline_params_vt);
283	            }
284	        }();
285	
286	        PipelineParamsKVNew pipeline_params_kv_new;
287	        pipeline_params_kv_new.role = warp_group_idx == 0
288	            ? MainloopPipelineKVNew::ThreadCategory::Producer
289	            : MainloopPipelineKVNew::ThreadCategory::Consumer;
290	        pipeline_params_kv_new.transaction_bytes = CollectiveMainloop::TmaTransactionBytesK;
291	        pipeline_params_kv_new.is_leader = warp_group_thread_idx == 0;
292	        pipeline_params_kv_new.num_consumers = NumMmaThreads;
293	        auto pipeline_k_new = cute::conditional_return<AppendKV>(MainloopPipelineKVNew(shared_storage.pipelines.pipeline_k_new, pipeline_params_kv_new, ClusterShape{}), nullptr);
294	        if constexpr (!SameHeadDim) {
295	            pipeline_params_kv_new.transaction_bytes = CollectiveMainloop::TmaTransactionBytesV;
296	        }
297	        auto pipeline_v_new = cute::conditional_return<AppendKV>(MainloopPipelineKVNew(shared_storage.pipelines.pipeline_v_new, pipeline_params_kv_new, ClusterShape{}), nullptr);
298	
299	        CollectiveMainloop mainloop;
300	        CollectiveEpilogue epilogue;
301	
302	        const int num_heads = get<2>(params.mainloop.shape_Q);
303	        Tensor gS_aux = make_tensor(make_gmem_ptr(params.mainloop.ptr_S_aux), make_shape(num_heads));
304	        Tensor sS_aux = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_s_aux.data()), SmemLayoutSAux{});
305	
306	        if(params.mainloop.ptr_S_aux && threadIdx.x < num_heads) {
307	            sS_aux(threadIdx.x) = gS_aux(threadIdx.x);
308	        }
309	
310	        // We need this to guarantee that the Pipeline init is visible to all producers and consumer blocks in the Cluster
311	        if constexpr (size(ClusterShape{}) > 1) {
312	            cute::cluster_arrive_relaxed();
313	            cute::cluster_wait();
314	        } else {
315	            __syncthreads();
316	        }
317	
318	        TileScheduler scheduler(reinterpret_cast<typename TileScheduler::SharedStorage*>(&shared_storage.pipelines.smem_scheduler));
319	
320	        if (warp_group_idx == 0) {  // Producer
321	            cutlass::arch::warpgroup_reg_dealloc<LoadRegisterRequirement>();
322	
323	            // The pipelines for AppendKV and main attention are different, since e.g. main attention
324	            // might use cp.async to load KV (if PagedKVNonTMA) while AppendKV always uses TMA to load
325	            // KV_new. Since the pipeline states are different, we have to manually sync to make
326	            // sure the two pipelines don't race when accessing smem_k and smem_v.
327	            PipelineState smem_pipe_write = cutlass::make_producer_start_state<MainloopPipelineK>();
328	            PipelineState smem_pipe_write_new = cutlass::make_producer_start_state<MainloopPipelineKVNew>();
329	            int work_idx = 0;
330	            int warp_idx_in_warpgroup = __shfl_sync(0xffffffff, (threadIdx.x / 32) % 4, 0);
331	            static constexpr bool SingleProducerWarp = NumProducerThreads == cutlass::NumThreadsPerWarp;
332	            if constexpr (SingleProducerWarp) {
333	                if (warp_idx_in_warpgroup != 0) { return; }
334	            }
335	            if (!SingleProducerWarp && warp_idx_in_warpgroup != 0) { scheduler.init_consumer(); }
336	
337	            cutlass::arch::wait_on_dependent_grids();
338	
339	            // Load Q, K, V
340	            for (auto work_tile_info = SingleProducerWarp || warp_idx_in_warpgroup == 0 ? scheduler.template get_initial_work</*IsProducerWarp=*/true>(params.scheduler) : scheduler.template get_initial_work</*IsProducerWarp=*/false>(params.scheduler);
341	                 work_tile_info.is_valid(params.scheduler);
342	                 work_tile_info = SingleProducerWarp || warp_idx_in_warpgroup == 0 ? scheduler.template get_next_work</*IsProducerWarp=*/true>(params.scheduler, work_tile_info) : scheduler.template get_next_work</*IsProducerWarp=*/false>(params.scheduler, work_tile_info)) {
343	
344	                auto block_coord = work_tile_info.get_block_coord(params.scheduler);
345	                SeqlenInfo_t seqlen_info{
346	                    get<2>(block_coord) /*bidb*/,
347	                    get<0>(params.mainloop.shape_Q),
348	                    !params.mainloop.ptr_pagetable ? size<0>(params.mainloop.shape_K) : size<0>(params.mainloop.shape_K) * size<1>(params.mainloop.shape_pagetable),
349	                    get<0>(params.mainloop.shape_K_new),
350	                    params.mainloop.cu_seqlens_q, params.mainloop.cu_seqlens_k, params.mainloop.cu_seqlens_k_new,
351	                    params.mainloop.seqused_q, params.mainloop.seqused_k, params.mainloop.leftpad_k,
352	                    params.mainloop.seqlens_rotary,
353	                    params.mainloop.cp_world_size,
354	                    params.mainloop.cp_rank,
355	                    params.mainloop.cp_tot_seqused_k
356	                };
357	                if constexpr (AppendKV) {
358	                    bool tile_new_valid = mainloop.load_kv_new(
359	                        params.mainloop, pipeline_k_new, pipeline_v_new,
360	                        smem_pipe_write_new, shared_storage, seqlen_info, block_coord, work_idx);
361	                    if (tile_new_valid) {
362	                        // if (threadIdx.x == 0) { printf("Producer: Before sync\n"); }
363	                        cutlass::arch::NamedBarrier::sync(NumMmaThreads + NumProducerThreads, static_cast<uint32_t>(FwdNamedBarriers::AppendKV) /*id*/);
364	                        // if (threadIdx.x == 0) { printf("Producer: After sync\n"); }
365	                    }
366	                }
367	                auto scheduler_prefetch = [&scheduler, &params, &work_tile_info]() {
368	                    scheduler.prefetch_next_work(params.scheduler, work_tile_info);
369	                };
370	                // pipeline_vt won't be used if we don't need to transpose V.
371	                mainloop.load(params.mainloop, pipeline_k, pipeline_v, pipeline_vt, smem_pipe_write,
372	                                         shared_storage, scheduler_prefetch, seqlen_info, block_coord, work_idx);
373	            }
374	            mainloop.load_tail(pipeline_k, pipeline_v, pipeline_vt, smem_pipe_write, shared_storage, work_idx);
375	        } else {  // Consumer
376	            cutlass::arch::warpgroup_reg_alloc<MmaRegisterRequirement>();
377	
378	            // Initialize matmul objects.
379	            TiledMmaPV tiled_mma_pv;
380	
381	            PipelineState smem_pipe_read;
382	            PipelineState smem_pipe_read_new;
383	            // We don't need separate variables smem_pipe_release_k and smem_pipe_release_v
384	            // (like in Cutlass's gemm) because the read and release pipeline states are always the same.
385	
386	            scheduler.init_consumer();
387	            mainloop.mma_init();
388	
389	            int work_idx = 0;
390	            CUTLASS_PRAGMA_NO_UNROLL
391	            for (auto work_tile_info = scheduler.template get_initial_work</*IsProducerWarp=*/false>(params.scheduler);
392	                 work_tile_info.is_valid(params.scheduler);
393	                 // get_next_work will be called before the epilogue
394	                 ) {
395	                auto block_coord = work_tile_info.get_block_coord(params.scheduler);
396	                int const bidb = get<2>(block_coord);
397	                SeqlenInfo_t seqlen_info{
398	                    bidb,
399	                    get<0>(params.mainloop.shape_Q),
400	                    !params.mainloop.ptr_pagetable ? size<0>(params.mainloop.shape_K) : size<0>(params.mainloop.shape_K) * size<1>(params.mainloop.shape_pagetable),
401	                    get<0>(params.mainloop.shape_K_new),
402	                    params.mainloop.cu_seqlens_q, params.mainloop.cu_seqlens_k, params.mainloop.cu_seqlens_k_new,
403	                    params.mainloop.seqused_q, params.mainloop.seqused_k, params.mainloop.leftpad_k,
404	                    params.mainloop.seqlens_rotary, params.mainloop.cp_world_size,
405	                    params.mainloop.cp_rank,
406	                    params.mainloop.cp_tot_seqused_k
407	                };
408	                if constexpr (AppendKV) {
409	                    bool tile_new_valid = mainloop.store_kv_new(
410	                        params.mainloop, pipeline_k_new, pipeline_v_new, smem_pipe_read_new,
411	                        threadIdx.x - MmaThreadOffset, shared_storage, seqlen_info, block_coord);
412	                    if (tile_new_valid) {
413	                        // if (threadIdx.x == 128) { printf("Consumer: Before sync\n"); }
414	                        // We need this sync so that the gmem write from the consumers is visible to the producer
415	                        // that might do TMA read after that.
416	                        asm volatile ("fence.proxy.async.global;");
417	                        cutlass::arch::NamedBarrier::arrive(NumMmaThreads + NumProducerThreads, static_cast<uint32_t>(FwdNamedBarriers::AppendKV) /*id*/);
418	                        // arrive is enough, we don't need sync. The producer will sync, which means
419	                        // after that sync we're guaranteed that the AppendKV pipeline have finished
420	                        // loading and consumer smem_k and smem_v.
421	                        // if (threadIdx.x == 128) { printf("Consumer: After sync\n"); }
422	                    }
423	                }
424	                // If there's tanh softcap, the scaling will be done before tanh.
425	                float softmax_scale_log2 = params.mainloop.softmax_scale_log2;
426	                if constexpr (Is_FP8 && !Has_softcap) {
427	                    int const bidh = get<1>(block_coord);
428	                    int const bidh_kv = !PackGQA ? params.mainloop.qhead_per_khead_divmod.divide(bidh) : bidh;
429	                    float const q_descale = params.mainloop.ptr_q_descale == nullptr ? 1.0f : params.mainloop.ptr_q_descale[bidb * get<0>(params.mainloop.stride_q_descale) + bidh_kv * get<1>(params.mainloop.stride_q_descale)];
430	                    float const k_descale = params.mainloop.ptr_k_descale == nullptr ? 1.0f : params.mainloop.ptr_k_descale[bidb * get<0>(params.mainloop.stride_k_descale) + bidh_kv * get<1>(params.mainloop.stride_k_descale)];
431	                    softmax_scale_log2 *= q_descale * k_descale;
432	                }
433	                flash::Softmax<!LargeHeadDimV ? 2 * (2 * kBlockM / NumMmaThreads) : 2, /*Max_offset=*/!Is_FP8 ? 0 : 8> softmax(softmax_scale_log2);
434	                // Attention output (GEMM-II) accumulator.
435	                Tensor tOrO = partition_fragment_C(tiled_mma_pv, select<0, 1>(TileShape_MNK_PV{}));
436	                bool tile_valid;
437	                if constexpr (!LargeHeadDimV) {
438	                    tile_valid = mainloop.mma(
439	                        params.mainloop, pipeline_k, pipeline_v, smem_pipe_read,
440	                        tOrO, softmax, threadIdx.x - MmaThreadOffset, work_idx, seqlen_info, block_coord, shared_storage);
441	                } else {  // mma_pv might not compile if !LargeHeadDimV
442	                    if (warp_group_idx == 1) {
443	                        tile_valid = mainloop.mma(
444	                            params.mainloop, pipeline_k, pipeline_v, smem_pipe_read,
445	                            tOrO, softmax, threadIdx.x - MmaThreadOffset, work_idx, seqlen_info, block_coord, shared_storage);
446	                    } else {
447	                        tile_valid = mainloop.mma_pv(
448	                            params.mainloop, pipeline_v, smem_pipe_read,
449	                            tOrO, softmax, threadIdx.x - MmaThreadOffset, seqlen_info, block_coord, shared_storage);
450	                    }
451	                }
452	                // Do this here before the epilogue so that the next tile is ready to go.
453	                work_tile_info = scheduler.template get_next_work</*IsProducerWarp=*/false>(params.scheduler, work_tile_info);
454	                if constexpr (Split && Varlen) {
455	                    if (!work_tile_info.is_valid(params.scheduler)) {  // Last tile
456	                        cutlass::arch::launch_dependent_grids();
457	                    }
458	                }
459	                if (tile_valid) {
460	                    // if (threadIdx.x == 128) { printf("Before epilogue, bid.x = %d, bid.y = %d, bid.z = %d, m_block = %d, bidb = %d, split_idx = %d\n", blockIdx.x, blockIdx.y, blockIdx.z, m_block, bidb, split_idx); }
461	                    epilogue.store(params.epilogue, tOrO, softmax.row_sum, shared_storage, tiled_mma_pv,
462	                                   threadIdx.x - MmaThreadOffset, block_coord);
463	                } else {
464	                    // Write 0 to gO and -inf to gLSE.
465	                    epilogue.store_zero(params.epilogue, threadIdx.x - MmaThreadOffset, block_coord);
466	                }
467	            }
468	            epilogue.store_tail();
469	        }
470	
471	    }
472	
473	};
474	
475	} // namespace flash
