707	        // tma_partition doesn't handle position_independent_swizzle_tensor correctly, so we need to do it manually
708	        auto block_tma_K = params.tma_load_K.get_slice(cluster_local_block_id.x);
709	        Tensor tKgK_TMA = group_modes<0, 3>(block_tma_K.partition_S(gK_TMA));  // (TMA, k, batch)
710	        Tensor tKsK_TMA = group_modes<0, 3>(block_tma_K.partition_D(sK));  // (TMA, PIPE)
711	        auto block_tma_V = params.tma_load_V.get_slice(cluster_local_block_id.x);
712	        Tensor tVgVt_TMA = group_modes<0, 3>(block_tma_V.partition_S(gVt_TMA));  // (TMA, k, batch)
713	        Tensor tVsVt_TMA = group_modes<0, 3>(block_tma_V.partition_D(sVt));  // (TMA, PIPE)
714	        auto [tQvgQv, tQvsQv] = [&] {
715	            if constexpr (HasQv) {
716	                auto shape_Qv = make_shape(get<0>(params.shape_Q), params.headdim_v, get<2>(params.shape_Q), get<3>(params.shape_Q));
717	                Tensor mQv = params.tma_load_Qv.get_tma_tensor(shape_Qv)(_, _, bidh, !is_varlen_q ? bidb : 0);
718	                Tensor gQv = local_tile(domain_offset(make_coord(seqlen_info.offset_q, _0{}), mQv), select<0, 2>(TileShape_MNK_QV{}), make_coord(m_block, _0{}));  // (M, Kv)
719	                auto block_tma_Qv = params.tma_load_Qv.get_slice(_0{});
720	                Tensor tQvgQv = group_modes<0, 3>(block_tma_Qv.partition_S(gQv));  // (TMA)
721	                Tensor tQvsQv = group_modes<0, 3>(block_tma_Qv.partition_D(sQv));  // (TMA)
722	                return cute::make_tuple(tQvgQv, tQvsQv);
723	            } else {
724	                return cute::make_tuple(nullptr, nullptr);
725	            }
726	        }();
727	
728	        // This is used to index into the batch dimension of mK and mV
729	        int const bidb_kv_idx = !is_varlen_k && !params.ptr_pagetable ? bidb_kv : 0;
730	
731	        using PagedKVManager_t = PagedKVManager<get<1>(TileShape_MNK{}), get<2>(TileShape_MNK{}), get<1>(TileShape_MNK_PV{}), NumProducerThreads, Element, Transpose_V || !IntraWGOverlap /*KV_Same_Iter*/>;
732	        PagedKVManager_t paged_kv_manager(
733	            params.ptr_pagetable, params.shape_pagetable, params.stride_pagetable,
734	            params.ptr_K, params.shape_K, params.stride_K,
735	            params.ptr_V, params.headdim_v, params.stride_V,
736	            params.page_size_divmod, params.blockN_per_page_size_divmod,
737	            bidb_kv, bidh_kv, thread_idx, seqlen_info.seqlen_k - n_offset, seqlen_info.leftpad_k + n_offset, bidb_kv_idx
738	        );
739	
740	        // Set up for transposing V, only used if Transpose_V
741	        S2RTiledCopyVt s2r_tiled_copy_vt;
742	        R2STiledCopyV r2s_tiled_copy_v;
743	        auto s2r_thr_copy_vt = s2r_tiled_copy_vt.get_thread_slice(thread_idx);
744	        auto r2s_thr_copy_v = r2s_tiled_copy_v.get_thread_slice(thread_idx);
745	        // flat_divide(sVt, LDSM_divide_shape{}):  (64, 8, kHeadDim / 64, kBlockN / 8, kStages)
746	        Tensor tTranssVt_ = s2r_thr_copy_vt.partition_S(flat_divide(sVt, LDSM_divide_shape{}));  // ((16, 1), 1, 1, kHeadDim / 64, kBlockN / 32, kStages)
747	        // flat_divide(sV, STSM_divide_shape{}):  (8, 16, kHeadDim / 8, (4, kBlockN / 64), kStages)
748	        Tensor tTranssV_ = r2s_thr_copy_v.partition_D(flat_divide(sV, STSM_divide_shape{}));  // ((16, 1), 1, 1, kHeadDim / 64, (2, kBlockN / 64), kStages)
749	        CUTE_STATIC_ASSERT_V(rank(tTranssVt_) == rank(tTranssV_));
750	        CUTE_STATIC_ASSERT_V(size<0>(tTranssVt_) == size<0>(tTranssV_));
751	        CUTE_STATIC_ASSERT_V(size<1>(tTranssVt_) == size<1>(tTranssV_));
752	        CUTE_STATIC_ASSERT_V(size<2>(tTranssVt_) == size<2>(tTranssV_));
753	        CUTE_STATIC_ASSERT_V(size<3>(tTranssVt_) == size<3>(tTranssV_));
754	        CUTE_STATIC_ASSERT_V(size<4>(tTranssVt_) == size<4>(tTranssV_));
755	        // Faster to have 2 LDSM.T, byte permute, STSM for better ILP
756	        static constexpr int Transpose_ILP = (size<2>(tTranssVt_) * size<3>(tTranssVt_)) % 2 == 0 ? 2 : 1;
757	        Tensor tTranssVt = logical_divide(group_modes<1, rank(tTranssVt_) - 1>(tTranssVt_), Shape<Underscore, Int<Transpose_ILP>>{});  // ((16, 1), (2, kHeadDim / 64 * kBlockN / 32 / 2), kStages)
758	        Tensor tTranssV = logical_divide(group_modes<1, rank(tTranssV_) - 1>(tTranssV_), Shape<Underscore, Int<Transpose_ILP>>{});  // ((16, 1), (2, kHeadDim / 64 * kBlockN / 32 / 2), kStages)
759	        auto transpose_V = [&](int stage) {
760	            if constexpr (Transpose_V) {
761	                #pragma unroll
762	                for (int i = 0; i < size<1, 1>(tTranssVt); ++i) {
763	                    Tensor tTransrV = make_fragment_like(tTranssV(_, make_coord(_, _0{}), _0{}));
764	                    static_assert(size<0>(tTransrV) == 16);
765	                    Tensor tTransrV_64 = recast<uint2>(tTransrV);
766	                    cute::copy(s2r_tiled_copy_vt, tTranssVt(_, make_coord(_, i), stage), tTransrV);
767	                    #pragma unroll
768	                    for (int j = 0; j < size(tTransrV_64); ++j) {
769	                        uint32_t upper = tTransrV_64[j].x;
770	                        uint32_t lower = tTransrV_64[j].y;
771	                        tTransrV_64[j].x = __byte_perm(upper, lower, 0x6420);
772	                        tTransrV_64[j].y = __byte_perm(upper, lower, 0x7531);
773	                    }
774	                    cute::copy(r2s_tiled_copy_v, tTransrV, tTranssV(_, make_coord(_, i), stage));
775	                }
776	            }
777	        };
778	
779	        uint16_t mcast_mask_kv = 0;
780	        if constexpr (cute::is_same_v<GmemTiledCopyKV, SM90_TMA_LOAD_MULTICAST>) {
781	            auto block_layout = Layout<ClusterShape>{}; // (m,n) -> block_id
782	            for (int m = 0; m < size<0>(block_layout); ++m) {
783	                mcast_mask_kv |= (uint16_t(1) << block_layout(m, cluster_local_block_id.y, _0{}));
784	            }
785	        }
786	
787	        auto load_K = [&] (int const n_block, auto const& smem_pipe_write, auto need_seqlenk_masking_type) {
788	            pipeline_k.producer_acquire(smem_pipe_write);
789	            if constexpr (!PagedKVNonTMA) {
790	                auto [n_block_idx, bidb_kv_idx] = paged_kv_manager.get_indices_for_K_TMA();
791	                copy(params.tma_load_K.with(*pipeline_k.producer_get_barrier(smem_pipe_write), mcast_mask_kv, TMA::CacheHintSm90::EVICT_LAST),
792	                    tKgK_TMA(_, n_block_idx, bidb_kv_idx), tKsK_TMA(_, smem_pipe_write.index()));
793	            } else {
794	                constexpr bool Seqlenk_mask = decltype(need_seqlenk_masking_type)::value;
795	                paged_kv_manager.template load_K<Seqlenk_mask>(n_block, sK_pi(_, _, smem_pipe_write.index()));
796	                pipeline_k.producer_commit(smem_pipe_write, cutlass::arch::cpasync_barrier_arrive);
797	            }
798	        };
799	
800	        auto load_V = [&] (int const n_block, auto const& smem_pipe_write, auto need_seqlenk_masking_type) {
801	            auto pipeline_v_load = cute::conditional_return<!Transpose_V>(pipeline_v, pipeline_vt);
802	            pipeline_v_load.producer_acquire(smem_pipe_write);
803	            if constexpr (!PagedKVNonTMA) {
804	                auto [n_block_idx, bidb_kv_idx] = paged_kv_manager.get_indices_for_V_TMA();
805	                copy(params.tma_load_V.with(*pipeline_v_load.producer_get_barrier(smem_pipe_write), mcast_mask_kv, TMA::CacheHintSm90::EVICT_LAST),
806	                    tVgVt_TMA(_, n_block_idx, bidb_kv_idx), tVsVt_TMA(_, smem_pipe_write.index()));
807	            } else {
808	                constexpr bool Seqlenk_mask = decltype(need_seqlenk_masking_type)::value;
809	                paged_kv_manager.template load_V<Seqlenk_mask>(n_block, sVcpasync(_, _, smem_pipe_write.index()));
810	                pipeline_v_load.producer_commit(smem_pipe_write, cutlass::arch::cpasync_barrier_arrive);
811	            }
812	        };
813	
814	        auto copy_Vt_to_V = [&] (auto const& smem_pipe_write) {
815	            // Instead of maintaining smem_pipe_read as a separate variable, we can just use smem_pipe_write,
816	            // and exploit the invariance that smem_pipe_write.phase() == smem_pipe_read.phase() ^ 1.
817	            // This saves 1 or 2 registers.
818	            PipelineState smem_pipe_read{smem_pipe_write.index(), smem_pipe_write.phase() ^ 1, smem_pipe_write.count()};
819	            pipeline_vt.consumer_wait(smem_pipe_read);
820	            pipeline_v.producer_acquire(smem_pipe_write);
821	            transpose_V(smem_pipe_write.index());
822	            // SMEM fence to make sure V is transposed before math
823	            cutlass::arch::fence_view_async_shared();
824	            pipeline_v.producer_commit(smem_pipe_write);
825	            // Very important: PipelineTmaAsync::consumer_release assumes that the warpgroup is synchronized
826	            // before calling. Without this we get race conditions.
827	            cutlass::arch::NamedBarrier::sync(cutlass::NumThreadsPerWarpGroup, cutlass::arch::ReservedNamedBarriers::TransposeBarrier /*id*/);
