829	        };
830	
831	        int n_block = n_block_max - 1;
832	
833	        int warp_idx_in_warpgroup = __shfl_sync(0xffffffff, (threadIdx.x / 32) % 4, 0);
834	        // If this is true, we're guaranteed that only the first warp will execute this function
835	        static constexpr bool SingleProducerWarp = NumProducerThreads == cutlass::NumThreadsPerWarp;
836	        bool should_load_KV = !Use_TMA_KV || ((SingleProducerWarp || warp_idx_in_warpgroup == 0) && cute::elect_one_sync());
837	
838	        if (should_load_KV) {
839	            if constexpr (PagedKVNonTMA) {
840	                paged_kv_manager.template load_page_table<true /*Seqlenk_mask*/, true /*First_iter*/>(n_block);
841	            } else {
842	                paged_kv_manager.template load_page_table_TMA<true /*First_iter*/>(n_block);
843	            }
844	            if constexpr (Transpose_V) { load_V(n_block, smem_pipe_write, cute::true_type{} /*Seqlenk_mask*/); }
845	            // if (thread_idx == 0) { printf("Producer: main load, before load_K, index = %d\n", smem_pipe_write.index());}
846	            load_K(n_block, smem_pipe_write, cute::true_type{} /*Seqlenk_mask*/);
847	            // if (thread_idx == 0) { printf("Producer: main load, after load K, index = %d\n", smem_pipe_write.index());}
848	        }
849	
850	        if constexpr (Use_TMA_Q) {
851	            // Wait for the MMA warpgroups to signal that smem_q is ready
852	            if (SingleProducerWarp || warp_idx_in_warpgroup == 0) {
853	                cutlass::arch::NamedBarrier::sync(NumMmaThreadsQK + cutlass::NumThreadsPerWarp, static_cast<uint32_t>(FwdNamedBarriers::QueryEmpty) /*id*/);
854	            }
855	
856	            if ((SingleProducerWarp || warp_idx_in_warpgroup == 0) && cute::elect_one_sync()) {
857	                shared_storage.pipelines.barrier_Q.arrive_and_expect_tx(TmaTransactionBytesQ);
858	                copy(params.tma_load_Q.with(reinterpret_cast<typename cutlass::arch::ClusterTransactionBarrier::ValueType&>(shared_storage.pipelines.barrier_Q), 0 /*mcast_mask*/, !Split ? TMA::CacheHintSm90::EVICT_FIRST : TMA::CacheHintSm90::EVICT_LAST),
859	                    tQgQ, tQsQ);
860	                if constexpr (HasQv) {
861	                    shared_storage.pipelines.barrier_Qv.arrive_and_expect_tx(TmaTransactionBytesQv);
862	                    copy(params.tma_load_Qv.with(reinterpret_cast<typename cutlass::arch::ClusterTransactionBarrier::ValueType&>(shared_storage.pipelines.barrier_Qv), 0 /*mcast_mask*/, !Split ? TMA::CacheHintSm90::EVICT_FIRST : TMA::CacheHintSm90::EVICT_LAST),
863	                        tQvgQv, tQvsQv);
864	                }
865	            }
866	        } else {  // Load Q with cp.async
867	            cutlass::arch::NamedBarrier::sync(NumMmaThreadsQK + NumProducerThreads, static_cast<uint32_t>(FwdNamedBarriers::QueryEmpty) /*id*/);
868	            Tensor mQ = make_tensor(make_gmem_ptr(params.ptr_Q + seqlen_info.offset_q * get<0>(params.stride_Q)), params.shape_Q_packed, params.stride_Q_packed)(_, _, bidh, !is_varlen_q ? bidb : 0);
869	            Tensor sQ_pi = cute::as_position_independent_swizzle_tensor(sQ);
870	            using PackGQAt = flash::PackGQAManager<get<0>(TileShape_MNK{}), get<2>(TileShape_MNK{}), NumProducerThreads, Element>;
871	            PackGQAt::load_Q(mQ, sQ_pi, params.qhead_per_khead_divmod, thread_idx, seqlen_info.seqlen_q, m_block);
872	            auto &barrier_Q = shared_storage.pipelines.barrier_Q;
873	            cutlass::arch::cpasync_barrier_arrive(reinterpret_cast<uint64_t*>(&barrier_Q));
874	            barrier_Q.arrive();
875	            if constexpr (HasQv) {
876	                Tensor mQv = make_tensor(make_gmem_ptr(params.ptr_Qv + seqlen_info.offset_q * get<0>(params.stride_Qv)), params.shape_Qv_packed, params.stride_Qv_packed)(_, _, bidh, !is_varlen_q ? bidb : 0);
877	                Tensor sQv_pi = cute::as_position_independent_swizzle_tensor(sQv);
878	                using PackGQAt = flash::PackGQAManager<get<0>(TileShape_MNK_QV{}), get<2>(TileShape_MNK_QV{}), NumProducerThreads, Element>;
879	                PackGQAt::load_Q(mQv, sQv_pi, params.qhead_per_khead_divmod, thread_idx, seqlen_info.seqlen_q, m_block);
880	                auto &barrier_Qv = shared_storage.pipelines.barrier_Qv;
881	                cutlass::arch::cpasync_barrier_arrive(reinterpret_cast<uint64_t*>(&barrier_Qv));
882	                barrier_Qv.arrive();
883	            }
884	        }
885	
886	        // Wait for the MMA WGs to signal that smem_v are ready and V can be copied from gmem
887	        // Need ClusterBarrier, not just NamedBarrier. Otherwise we might have CTA 0 finishing the
888	        // TMA store on O first, call TMA multicast load on V, before CTA 1 can finishing TMA store on O.
889	        // if (thread_idx == 0) { printf("Producer: main load, before barrier_O, work_idx = %d\n", work_idx);}
890	        shared_storage.pipelines.barrier_O.wait((work_idx + 1) % 2);
891	        // if (thread_idx == 0) { printf("Producer: main load, after barrier_O\n");}
892	
893	        if constexpr (!Transpose_V && !IntraWGOverlap) {
894	            if (should_load_KV) { load_V(n_block, smem_pipe_write, cute::true_type{} /*Seqlenk_mask*/); }
895	        }
896	        int n_block_prev = n_block;
897	        --n_block;
898	        #pragma unroll (!Transpose_V && Use_TMA_KV ? 2 : 1)
899	        for (; n_block >= n_block_min; --n_block) {
900	            PipelineState smem_pipe_write_v = smem_pipe_write; // copy the state, write_v is always 1 step behind
901	            ++smem_pipe_write;
902	            if (should_load_KV) {
903	                if constexpr (PagedKVNonTMA) {
904	                    paged_kv_manager.template load_page_table<false /*Seqlenk_mask*/>(n_block);
905	                } else {
906	                    paged_kv_manager.load_page_table_TMA(n_block);
907	                }
908	                if constexpr (Transpose_V) { load_V(n_block, smem_pipe_write, cute::false_type{} /*Seqlenk_mask*/); }
909	                load_K(n_block, smem_pipe_write, cute::false_type{} /*Seqlenk_mask*/);
910	                if constexpr (!Transpose_V) {
911	                    if constexpr (IntraWGOverlap) {
912	                        load_V(n_block_prev, smem_pipe_write_v, cute::true_type{} /*Seqlenk_mask*/);
913	                    } else {
914	                        load_V(n_block, smem_pipe_write, cute::false_type{} /*Seqlenk_mask*/);
915	                    }
916	                }
917	            }
918	            n_block_prev = n_block;
919	            if constexpr (Transpose_V) { copy_Vt_to_V(smem_pipe_write_v); }
920	        }
921	        scheduler_prefetch();
922	        if constexpr (!Transpose_V && IntraWGOverlap) {
923	            if (should_load_KV) { load_V(n_block_prev, smem_pipe_write, cute::true_type{} /*Seqlenk_mask*/); }
924	        }
925	        if constexpr (Transpose_V) { copy_Vt_to_V(smem_pipe_write); }
926	        ++smem_pipe_write;
927	        // At the end, all threads have the correct smem_pipe_write.
928	        ++work_idx;
929	    }
