params.num_splits = num_splits <= 0 ? get_num_splits(params) : num_splits;
// printf("Num splits = %d.\n", params.num_splits);
params.pack_gqa = pack_gqa_.has_value() ? pack_gqa_.value() : get_pack_gqa(params);
